+    } else {
+        sub_limbs(MODULUS, r).0
+    };
+
+    // value is a * 2^256, so a^-1 * 2^256 = almost * 2^(512 - k).
+    let almost = montgomery_mul(almost, R2);
+    if k <= 256 {
+        montgomery_mul(montgomery_mul(almost, R2), pow2_mod(256 - k))
+    } else {
+        montgomery_mul(almost, pow2_mod(512 - k))
+    }
